/* SimStory Studio — standalone, no API, no account. */
(() => {
'use strict';
const KEY='simstory-studio-v1';
const $=x=>document.querySelector(x);
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pick=a=>a[Math.floor(Math.random()*a.length)];
const uniq=a=>[...new Set(a)];
const samplePrefs=()=>({name:'',age:'Young Adult',trait0:'Loner',trait1:'',trait2:'',colors:['Purple','Blue'],theme:'any',mood:'balanced',story:'',pronouns:'Surprise me',lifeState:'Human',relationship:'Single',housing:'Surprise me',world:'',aspiration:'',career:'',hobby:'',skill0:'',skill1:'',skill2:'',style:'',money:'modest',notes:'',householdCount:4});
const fresh=()=>({tab:'studio',mode:'single',owned:[...DATA.featured],active:[...DATA.featured],prefs:samplePrefs(),current:null,locks:[],library:[],history:[],sparks:null,spotlight:-1,savedPrompts:[],dice:{question:'Should my Sim accept the proposal?',mode:'nuanced',bias:'even',custom:'',preset:'proposal',result:null,history:[]},gameIcons:true,iconSearch:'',iconGroup:'all',packSearch:'',librarySearch:'',sections:{personality:true,identity:true,lifestyle:false,plot:false},created:Date.now()});
let state;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'null');state=saved&&typeof saved==='object' ? {...fresh(),...saved,prefs:{...samplePrefs(),...(saved.prefs||{})},dice:{...fresh().dice,...(saved.dice||{})},savedPrompts:saved.savedPrompts||[]}:fresh(); }catch{state=fresh();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Unable to save locally. Export a backup to keep your ideas.')}}
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),2800)}
const packName=id=>DATA.packs.find(p=>p.id===id)?.name||id;
const activePacks=()=>new Set(['base',...state.active.filter(p=>state.owned.includes(p))]);
const allowed=(list,set=activePacks())=>list.filter(x=>set.has(x.pack));
const noClash=(a,b)=>a.name!==b.name&&!a.opposes?.includes(b.name)&&!b.opposes?.includes(a.name);
const weights=(item,tags,packs,focusPack)=>{let n=1;const t=item.tags||[];for(const z of tags||[])if(t.includes(z))n+=4;if(item.pack===focusPack)n+=5;if(item.pack!=='base'&&packs.has(item.pack))n+=1.5;if(DATA.featured.includes(item.pack))n+=.9;return n;};
function weighted(list,tags=[],focusPack='',exclusions=[]){const used=new Set(exclusions.map(x=>typeof x==='string'?x:x.name));let arr=list.filter(x=>!used.has(x.name));if(!arr.length)arr=list;if(!arr.length)return null;const sets=activePacks();const total=arr.reduce((n,x)=>n+weights(x,tags,sets,focusPack),0);let r=Math.random()*total;for(const x of arr){r-=weights(x,tags,sets,focusPack);if(r<=0)return x;}return arr[arr.length-1]}
function storyVars(s,info){return String(s||'').replace(/\{(name|world|career|hobby|goal|rival)\}/g,(_,k)=>info[k]??'');}
function validVal(list,value){return list.some(x=>x.name===value)}
function buildProfile(pref=state.prefs,prev=null,keeps=new Set(state.locks),focusPack=''){
 const packs=activePacks();const item=(key,items,tags,focus,overrides)=>{
  const user=overrides??pref[key];if(user&&validVal(items,user))return items.find(x=>x.name===user);
  const prior=(prev&&keeps.has(key)) ? prev[key]:null;
  if(prior&&validVal(items,typeof prior==='string'?prior:prior.name))return items.find(x=>x.name===(prior.name||prior));
  return weighted(items,tags,focus);
 };
 const permitted=DATA.stories.filter(x=>packs.has(x.pack));
 const tags0=pref.theme&&pref.theme!=='any'?[pref.theme]:[];
 const [rawS,storyKeep]=[pref.story||'',prev&&keeps.has('story')?prev.story:null];
 let story;
 if(rawS)story=permitted.find(s=>s.title===rawS);
 if(!story&&storyKeep)story=permitted.find(s=>s.title===storyKeep.title);
 if(!story)story=weighted(permitted.map(s=>({...s,name:s.title})),tags0,focusPack);
 if(!story)story=DATA.stories[0];
 const tags=uniq([...tags0,...story.tags]);
 const age=pref.age||'Young Adult';
 const name=String(pref.name||'').trim() || (prev&&keeps.has('name')?prev.name:null) || `${pick(DATA.nameFirst)} ${pick(DATA.nameLast)}`;
 const availableTraits=allowed(DATA.traits,packs);
 const traits=[];
 for(let i=0;i<(age==='Teen'?2:3);i++){
  const key='trait'+i;let match=availableTraits.find(x=>x.name===pref[key]);
  if(!match&&prev&&keeps.has(key))match=availableTraits.find(x=>x.name===prev.traits?.[i]);
  if(match&&!traits.some(t=>t.name===match.name))traits.push(match);
  else{const options=availableTraits.filter(x=>traits.every(y=>noClash(x,y)));traits.push(weighted(options.length?options:availableTraits.filter(x=>!traits.some(y=>y.name===x.name)),tags,focusPack)||availableTraits[0]);}
 }
 const aspiration=item('aspiration',allowed(DATA.aspirations,packs),tags,focusPack);
 let career;
 if(age==='Teen'){
   const teenOptions=[{name:'Part-time job',pack:'base',tags:['career','money']},{name:'Student / no job',pack:'base',tags:['creative','family']},{name:'After-school hustle',pack:'base',tags:['creative','money']}];
   career=item('career',teenOptions,tags,focusPack);
 }else {
 const preferredCareers={'Working for Grim':'Reaper','The Midnight Baker':'Culinary','The Small-Business Gamble':'Self-employed (player-directed)','The Family Studio':'Self-employed (player-directed)','The Ranch Is the Dream':'Self-employed (player-directed)','The Dating Experiment':'Romance Consultant','The Dating Experiment!':'Romance Consultant','The Noble Outsider':'Noble','The Haunted Side Hustle':'Paranormal Investigator','An Almost Famous Life':'Actor'};
 const recommended=(!pref.career && !(prev&&keeps.has('career')) && preferredCareers[story.title])?preferredCareers[story.title]:null;
 career=item('career',allowed(DATA.careers,packs),tags,focusPack,recommended);
 }
 const preferredHobbies={'The Midnight Baker':'Selling food from a stand','The Small-Business Gamble':'Pottery','The Family Studio':'Pottery','The Ranch Is the Dream':'Making nectar','The Last Thing on the List':'Studying Thanatology','Working for Grim':'Studying Thanatology','A Second Chance at Love':'Dating through Cupid’s Corner','The Dating Experiment':'Dating through Cupid’s Corner','A Crystal-Clear Secret':'Crafting crystal jewelry','The Slow Stitch Club':'Knitting','The Haunted Side Hustle':'Ghost hunting','The Green Comeback':'Fabrication','The Village Outsider':'Gardening'};
 const preferredHobby=(!pref.hobby && !(prev&&keeps.has('hobby'))&&preferredHobbies[story.title])?preferredHobbies[story.title]:null;
 const hobby=item('hobby',allowed(DATA.hobbies,packs),tags,focusPack,preferredHobby);
 const eligibleWorlds=allowed(DATA.worlds,packs).filter(x=>x.residential);
 let world=item('world',eligibleWorlds,tags,story.pack);
 if(!world)world=DATA.worlds[0];
 const style=item('style',DATA.styles,tags,focusPack);
 const palette=(pref.colors?.length ? pref.colors : (prev&&keeps.has('colors')?prev.colors:null))||[];
 const colors=(palette.length?palette:[...new Set([pick(DATA.colors.slice(0,14)).name,pick(DATA.colors).name,pick(DATA.colors).name])]);
 const known={name,world:world.name,career:career?.name||'Personal projects',hobby:hobby?.name||'Trying new hobbies',goal:aspiration?.name||'A meaningful life',rival:pick(DATA.nameFirst)};
 const mood=pref.mood||'balanced';
 const inciting=pick(DATA.sceneStarts);
 const bg=pick(DATA.backgrounds),quirk=pick(DATA.quirks),strength=pick(DATA.strengths),weakness=pick(DATA.weaknesses);
 const daily=storyVars(story.weeks[0],known);
 const mainArc=storyVars(story.premise,known);
 const shortGoals=[daily,`Spend one focused session on ${known.hobby.toLowerCase()}.`,`Meet one new Sim or strengthen an existing relationship.`];
 const longGoals=[`Make meaningful progress toward ${known.goal}.`,`Reach a personal milestone in ${known.career}.`,`Build a living space that reflects ${style.name.toLowerCase()} style and feels like home.`];
 const scenes=[inciting,`While working on ${known.hobby.toLowerCase()}, ${name.split(' ')[0]} meets someone with a surprising connection to the past.`,`A conversation in ${world.name} forces a choice between comfort and growth.`];
 const addTwist= mood==='cozy'?'A small misunderstanding prompts a sweet, honest conversation.':mood==='dramatic'?'Someone hides the truth until it threatens a valued relationship.':mood==='chaotic'?'Two unrelated problems explode on exactly the same evening.':storyVars(story.twist,known);
 const lifeStates=[{name:'Human',pack:'base'},{name:'Ghost',pack:'base'},{name:'Alien',pack:'gtw'},{name:'Vampire',pack:'vamp'},{name:'Mermaid',pack:'il'},{name:'Spellcaster',pack:'magic'},{name:'Werewolf',pack:'were'},{name:'Fairy',pack:'nature'}];
 const lifeState=lifeStates.find(x=>x.name===pref.lifeState&&packs.has(x.pack))?.name||'Human';
   const skillChoices=allowed(DATA.skills,packs);
  const skillLinks={
   'Pottery':'Pottery','Tattooing':'Tattooing','Making nectar':'Nectar Making','Horse riding':'Horse Riding',
   'Studying Thanatology':'Thanatology','Crafting crystal jewelry':'Gemology',
   'Baking':'Cooking','Making waffles and pizza':'Cooking','Selling food from a stand':'Cooking',
   'Playing piano':'Piano','Writing a novel':'Writing','Painting':'Painting','Photography':'Photography',
   'Programming':'Programming','Woodworking':'Handiness','Gardening':'Gardening',
   'Pet training':'Pet Training','Yoga and meditation':'Wellness','Knitting':'Knitting',
   'DJ mixing':'DJ Mixing','Learning to dance':'Dancing','Acting':'Acting',
   'Fabrication':'Fabrication','Rock climbing':'Rock Climbing','Learning spellcraft':'Logic',
   'Ghost hunting':'Medium','Bowling':'Bowling','Robotics':'Robotics',
   'Caring for farm animals':'Gardening','Fishing':'Fishing'};
  const careerLinks={'Culinary':'Cooking','Writer':'Writing','Freelance Writer':'Writing','Painter':'Painting',
   'Freelance Artist':'Painting','Athlete':'Fitness','Tech Guru':'Programming','Freelance Programmer':'Programming',
   'Romance Consultant':'Romance','Reaper':'Thanatology','Undertaker':'Thanatology',
   'Interior Decorator':'Painting','Paranormal Investigator':'Medium','Actor':'Acting',
   'Veterinarian (clinic owner)':'Veterinarian','Scientist':'Logic','Detective':'Logic',
   'Business':'Charisma','Social Media':'Charisma','Politician':'Charisma','Entertainer':'Guitar'};
  const aspirationLinks={'Master Chef':'Cooking','Bestselling Author':'Writing','Painter Extraordinaire':'Painting',
   'Expert Nectar Maker':'Nectar Making','Championship Rider':'Horse Riding','Romantic Explorer':'Romance',
   'Paragon Partner':'Romance','Ghost Historian':'Thanatology','Esteemed Entrepreneur':'Pottery',
   'Master Mentor':'Charisma','Musical Genius':'Piano','Soulmate':'Charisma','Bodybuilder':'Fitness',
   'Renaissance Sim':'Logic','Computer Whiz':'Programming','Freelance Botanist':'Gardening',
   'Angling Ace':'Fishing','Master Vampire':'Vampire Lore','Lord of the Knits':'Knitting','Crystal Crafter':'Gemology'};
  const chosenSkills=[];
  for(let i=0;i<3;i++){
   const key='skill'+i;
   const fixed=pref[key]||((prev&&keeps.has(key))?prev.skills?.[i]?.name:'');
   let candidate=skillChoices.find(x=>x.name===fixed&&!chosenSkills.some(s=>s.name===x.name));
   let reason='Suggested from this Sim’s personality and story.';
   if(candidate)reason='Your chosen focus skill.';
   if(!candidate){
    const suggestions=[skillLinks[hobby?.name],careerLinks[career?.name],aspirationLinks[aspiration?.name]]
      .filter(Boolean).map(name=>skillChoices.find(s=>s.name===name)).filter(Boolean)
      .filter(s=>!chosenSkills.some(x=>x.name===s.name));
    candidate= i<2?suggestions[0]:null;
    if(candidate)reason=candidate.name===skillLinks[hobby?.name]?'Supports their favorite hobby.':candidate.name===careerLinks[career?.name]?'Useful for their career path.':'Connects to their aspiration.';
   }
   if(!candidate){const remain=skillChoices.filter(x=>!chosenSkills.some(s=>s.name===x.name));candidate=weighted(remain,tags,focusPack);}
   if(candidate){const maxLevel=({ 'Nectar Making':5,'Thanatology':5,'Medium':5,'Photography':5,'Bowling':5,'Dancing':5,'Pet Training':5,'Entrepreneur':5,'Cross-Stitch':5,'Juice Fizzing':5,'Selvadoradian Culture':5,'Vampire Lore':15 })[candidate.name]||10;
    chosenSkills.push({...candidate,reason,target:i===0?`Master at level ${maxLevel}`:i===1?`Build toward level ${Math.min(maxLevel,6)}`:`Try reaching level ${Math.min(maxLevel,3)}`});}
  }
const result={kind:'single',id:'g'+Date.now()+'_'+Math.floor(Math.random()*1e6),generatedAt:new Date().toISOString(),name,age,pronouns:pref.pronouns||'Surprise me',lifeState,relationship:pref.relationship||'Single',housing:pref.housing||'Surprise me',traits:traits.map(x=>x.name),aspiration:aspiration.name,career:career.name,hobby:hobby.name,skills:chosenSkills,world:world.name,worldDesc:world.desc,style:style.name,wardrobe:style.wardrobe,room:style.home,colors,story:{title:story.title,pack:story.pack,theme:tags[0]||'creative',premise:mainArc,want:storyVars(story.want,known),fear:storyVars(story.fear,known),friction:storyVars(story.friction,known),secret:storyVars(story.secret,known),weeks:story.weeks.map(x=>storyVars(x,known)),twist:addTwist},background:bg,quirk,strength,weakness,shortGoals,longGoals,scenes,startingFunds:pref.money||'modest',mood,notes:pref.notes||'',packUsed:uniq([story.pack,...traits.map(t=>t.pack),aspiration.pack,career.pack,hobby.pack,world.pack,...chosenSkills.map(x=>x.pack)].filter(x=>x!=='base'))};
 return result;
}
function buildHousehold(){
 const count=Math.max(2,Math.min(6,Number(state.prefs.householdCount)||4));
 const pool=state.active.length?state.active:['base'];
 const assigned=uniq([...pool,'base']);
 const focusTags=['creative','romance','career','mystery','ranch','social','family','adventure','money'];
 const cast=[];
 for(let i=0;i<count;i++){
   const pr=i===0?{...state.prefs}:{...state.prefs,name:'',trait0:'',trait1:'',trait2:'',aspiration:'',career:'',hobby:'',skill0:'',skill1:'',skill2:'',style:'',theme:focusTags[(i-1)%focusTags.length],colors:[],notes:''};
   const character=buildProfile(pr,null,new Set(),assigned[i%assigned.length]);
   if(state.prefs.world&&DATA.worlds.some(w=>w.name===state.prefs.world)){character.world=state.prefs.world;}
   while(cast.some(x=>x.name===character.name))character.name=`${pick(DATA.nameFirst)} ${pick(DATA.nameLast)}`;
   cast.push(character);
 }
 // The household is set in the first Sim's world, regardless of each Sim's initial story setting.
 const world=state.prefs.world||cast[0].world;
 cast.forEach(c=>{c.world=world;c.story.premise=c.story.premise.replace(/\b(?:Willow Creek|Oasis Springs|Newcrest|Windenburg|San Myshuno|Brindleton Bay|Del Sol Valley|Sulani|Britechester|Evergreen Harbor|Mt\. Komorebi|Henford-on-Bagley|Copperdale|San Sequoia|Chestnut Ridge|Tomarang|Ciudad Enamorada|Ravenwood|Nordhaven|Innisgreen|Gibbi Point|Ondarion|Forgotten Hollow|Glimmerbrook|StrangerVille|Moonwood Mill|Tartosa)\b/g,world)});
 const premise=pick(DATA.housePremises);
 const pairText=['One is fascinated by the other’s confidence, but hides it behind sarcasm.','They are becoming unlikely friends through shared late-night conversations.','Their opposite attitudes toward money create friction.','They share a hobby and keep trying to outdo each other.','One has a crush that the other may not have noticed.','They disagree about noise, guests and what counts as a clean kitchen.','They secretly plan a birthday surprise together.','They made an agreement about dating that may prove difficult to keep.','One is helping the other through a personal setback.'];
 const relationships=[];
 for(let i=0;i<cast.length-1;i++)relationships.push({pair:`${cast[i].name.split(' ')[0]} + ${cast[i+1].name.split(' ')[0]}`,dynamic:pick(pairText)});
 const combined=uniq(cast.flatMap(c=>c.packUsed));
 return {kind:'household',id:'h'+Date.now()+'_'+Math.floor(Math.random()*1e6),generatedAt:new Date().toISOString(),title:premise.name,world,count,cast,relationships,premise:premise.desc,goal:premise.goal,conflict:premise.conflict,
  weeks:['Move in, assign rooms, share a meal and notice the first friendship or disagreement.','Focus on each roommate’s first personal milestone; plan one group outing.','Introduce a party, unexpected visitor or romance complication.','Revisit the house rules and decide what each Sim wants next.'],
  packUsed:combined,notes:state.prefs.notes||''};
}
function generate(keepOverride=null){if(state.mode==='household'){state.current=buildHousehold();state.locks=[]}else{state.current=buildProfile(state.prefs,state.current,keepOverride||new Set(state.locks));}state.history.unshift(state.current);state.history=state.history.slice(0,15);persist();render();if(innerWidth<950)$('.result-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
function topbar(){return `<div class="topbar"><div class="breadcrumbs">✧ SIMSTORY STUDIO / ${E(({studio:'SIM BUILDER',packs:'PACK COLLECTION',library:'YOUR LIBRARY',sparks:'INSPIRATION DECK',icons:'ICON LIBRARY'})[state.tab])}</div><div class="top-actions"><span class="topbadge">✦ ${state.active.length} packs active</span><span class="topbadge">♡ ${state.library.length} saved ideas</span><button class="topbadge icon-toggle" data-action="toggle-icons" title="Real in-game icons included locally; works offline">${state.gameIcons?'◈ Game icons: on':'◈ Game icons: off'}</button></div></div>`}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-symbol">✦</div><div><strong>SimStory Studio</strong><small>Imagine · Create · Play</small></div></div><div class="navgroup">Create</div>${[
 ['studio','✧','Sim Builder'],['sparks','⚡','Inspo Deck'],['library','♡','Saved Ideas'],['packs','◈','My Packs'],['icons','◉','Game Icons']].map(([id,ic,name])=>`<button class="navbtn ${state.tab===id?'active':''}" data-action="tab" data-id="${id}" aria-label="${name}"><span class="navico">${ic}</span>${name}${id==='library'?`<span class="count">${state.library.length}</span>`:''}</button>`).join('')}<div class="side-card"><div class="side-star">✷</div><h3>Need a little chaos?</h3><p>Got a messy in-game decision? Let the Decision Dice settle it.</p><button data-action="tab" data-id="sparks">Roll the Decision Dice 🎲</button></div><div class="sidefoot">Unofficial fan-made creative tool.<br>Everything works offline · Icons bundled</div></aside>`}
function hero(){return `<div class="hero"><div><div class="eyebrow">✦ The character & storyline lab</div><h1>Your next Sim has a story to tell.</h1><p>Start with a detail or start with nothing. Choose your packs, keep your favorites and generate the rest—without losing your ideas.</p></div><div class="hero-art"><span>🔮</span><small>✨</small></div></div>`}
function options(list,val,empty='Surprise me'){return `<option value="">${E(empty)}</option>`+list.map(x=>{const name=typeof x==='string'?x:x.name;const label=typeof x==='string'?x:(x.label||x.name);const pack=typeof x==='string'?'base':x.pack;return `<option value="${E(name)}" ${val===name?'selected':''}>${E(label)}${pack&&pack!=='base'?' · '+E(packName(pack)):''}</option>`}).join('')}
function fieldSelect(key,label,items,empty='Surprise me',help=''){return `<div class="field"><label for="f-${key}">${E(label)}</label><select id="f-${key}" data-pref="${key}">${options(items,state.prefs[key],empty)}</select>${help?`<small class="help">${E(help)}</small>`:''}</div>`}
function detailsPanel(id,label,content,hint){return `<details class="accordion" data-panel="${id}" ${state.sections[id]?'open':''}><summary>${label}<span class="hint">${hint}</span></summary>${content}</details>`}
function fieldData(){const p=state.prefs;const sets=activePacks();const genderless=['Teen','Young Adult','Adult','Elder'];let html='';
 html+=detailsPanel('identity','01 · Identity & format',`<div class="fields split-fields"><div class="field"><label for="f-name">Name</label><input id="f-name" data-pref="name" value="${E(p.name)}" placeholder="Surprise me" maxlength="80"/></div>${fieldSelect('age','Life stage',genderless,'Young Adult')}<div class="field"><label for="f-pronouns">Pronouns (for your reference)</label><select id="f-pronouns" data-pref="pronouns">${['Surprise me','She/Her','He/Him','They/Them'].map(x=>`<option value="${x}" ${p.pronouns===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="f-lifeState">Life state</label><select id="f-lifeState" data-pref="lifeState">${[{name:'Human',pack:'base'},{name:'Ghost',pack:'base'},{name:'Alien',pack:'gtw'},{name:'Vampire',pack:'vamp'},{name:'Mermaid',pack:'il'},{name:'Spellcaster',pack:'magic'},{name:'Werewolf',pack:'were'},{name:'Fairy',pack:'nature'}].filter(x=>sets.has(x.pack)).map(x=>`<option value="${x.name}" ${p.lifeState===x.name?'selected':''}>${x.name}</option>`).join('')}</select></div>${state.mode==='household'?`<div class="field"><label for="f-householdCount">Number of roommates</label><select id="f-householdCount" data-pref="householdCount">${[2,3,4,5,6].map(x=>`<option ${Number(p.householdCount)===x?'selected':''} value="${x}">${x} Sims</option>`).join('')}</select></div>`:''}<div class="field"><label for="f-money">Starting situation</label><select id="f-money" data-pref="money">${[['tight','Barely scraping by'],['modest','Modest starter funds'],['comfortable','Comfortable'],['wealthy','Well-off']].map(([a,b])=>`<option value="${a}" ${p.money===a?'selected':''}>${b}</option>`).join('')}</select></div></div>`,state.mode==='household'?'Your choices shape the first roommate':'Age, name & starting funds');
 html+=detailsPanel('personality','02 · Personality & appearance',`<div class="fields"><div class="field wide"><span class="lab">${p.age==='Teen'?'Two':'Three'} CAS personality traits</span><span class="help">Anything you choose stays fixed. Empty slots get filled automatically, avoiding common trait conflicts.</span></div>${(p.age==='Teen'?[0,1]:[0,1,2]).map(i=>fieldSelect('trait'+i,'Trait '+(i+1),allowed(DATA.traits,sets),i===0?'Surprise me':'Choose or generate')).join('')}<div class="field wide"><span class="lab">Favorite colors (choose any)</span><div class="color-grid">${DATA.colors.map(c=>`<button type="button" class="colorpick ${p.colors.includes(c.name)?'on':''}" data-action="color" data-id="${E(c.name)}" aria-pressed="${p.colors.includes(c.name)}"><span class="sw" style="background:${c.hex}"></span>${E(c.name)}</button>`).join('')}</div></div>${fieldSelect('style','Aesthetic / fashion style',DATA.styles,'Match the personality')}</div>`, 'Fix what you already know');
 html+=detailsPanel('lifestyle','03 · Aspirations, career, skills & home',`<div class="fields">${fieldSelect('aspiration','Aspiration',allowed(DATA.aspirations,sets))}${fieldSelect('career','Career',p.age==='Teen'?[{name:'Part-time job'},{name:'Student / no job'},{name:'After-school hustle'}]:allowed(DATA.careers,sets))}${fieldSelect('hobby','Hobby / side project',allowed(DATA.hobbies,sets))}<div class="field wide"><span class="lab">Skills to focus on</span><span class="help">Optional: choose any or leave blank for tailored suggestions. Skills can be practiced and mastered; traits are personality characteristics.</span></div>${[0,1,2].map(i=>fieldSelect('skill'+i,['Main skill to master','Secondary skill','Bonus skill'][i],allowed(DATA.skills,sets),'Suggest one')).join('')}${fieldSelect('world','Residential world',allowed(DATA.worlds,sets).filter(x=>x.residential))}<div class="field"><label for="f-relationship">Starting relationship status</label><select id="f-relationship" data-pref="relationship">${['Single','Casually dating','In a relationship','Engaged','Married','Recently separated'].map(x=>`<option value="${x}" ${p.relationship===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="f-housing">Housing style</label><select id="f-housing" data-pref="housing">${['Surprise me','Tiny starter','Shared house','Apartment / rental','Family home','Cottage','Ranch property','Luxury home','Fixer-upper'].map(x=>`<option value="${x}" ${p.housing===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`, 'Every option respects active packs');
 html+=detailsPanel('plot','04 · Story direction',`<div class="fields">${fieldSelect('theme','What type of story?',DATA.themes.filter(x=>x[0]!=='any').map(([id,name])=>({name:id,label:name})),'Surprise me')}${fieldSelect('story','Story seed (optional)',DATA.stories.filter(x=>sets.has(x.pack)).map(x=>({name:x.title,pack:x.pack}))) }<div class="field"><label for="f-mood">Drama level</label><select id="f-mood" data-pref="mood">${[['cozy','Cozy / low drama'],['balanced','Balanced realism + drama'],['dramatic','Messy relationships'],['chaotic','Maximum chaos']].map(([a,b])=>`<option value="${a}" ${p.mood===a?'selected':''}>${b}</option>`).join('')}</select></div><div class="field wide"><label for="f-notes">My own ideas / notes</label><textarea data-pref="notes" id="f-notes" placeholder="e.g. She hates her sister, wants a bakery, and needs an enemies-to-lovers arc...">${E(p.notes)}</textarea><small class="help">Your notes are saved with the generated idea. Story templates are handcrafted, so they won't automatically interpret free-text instructions.</small></div></div>`, 'Cozy, romance, ambition, chaos…');
 return html;
}
function prettyTheme(theme){return DATA.themes.find(x=>x[0]===theme)?.[1]||theme}
function studio(){return `${hero()}<div class="split"><section class="card cardpad config-panel"><div class="card-head"><div><h2>✧ Character ingredients</h2><p>Fill as much or as little as you like.</p></div><button class="btn tiny" data-action="reset">↺ Reset</button></div><div class="segmented"><button class="${state.mode==='single'?'selected':''}" data-action="mode" data-id="single">✦ One Sim</button><button class="${state.mode==='household'?'selected':''}" data-action="mode" data-id="household">♧ Roommate Household</button></div><div class="notice">Using <b>${state.active.length} selected packs</b> + Base Game. <button data-action="tab" data-id="packs" class="iconbtn" style="font-weight:800;width:auto;color:#7453b1;text-decoration:underline;font-size:11px">Edit packs ↗</button>${state.mode==='household'?'<br>Your fixed character details apply to roommate #1. The other roommates are generated around them.':''}</div>${fieldData()}<div class="generate-bottom"><button class="btn primary big" data-action="generate">✦ ${state.current?'Generate another idea':'Create my idea'}</button></div></section><section class="card result-panel">${!state.current?`<div class="result-empty"><span class="empty-icon">🔮</span><h3>Your plot twist awaits.</h3><p>Choose some details and press Generate to reveal a new Sim.</p></div>`:state.current.kind==='single'?renderProfile(state.current):renderHousehold(state.current)}</section></div><div class="footer">Made for storytelling, not speedrunning. Real Sims 4 icon files are bundled from your supplied icon pack and work offline; unmatched entries are clearly labeled. Not affiliated with EA. ✧</div>`}
function lockBtn(k){return `<button class="iconbtn ${state.locks.includes(k)?'locked':''}" data-action="lock" data-id="${k}" title="${state.locks.includes(k)?'Unlock':'Lock this result when regenerating'}" aria-label="${state.locks.includes(k)?'Unlock':'Lock'} ${k}">${state.locks.includes(k)?'🔒':'♧'}</button>`}
// Exact game artwork is mapped by type AND gameplay name. No generic substitute image.
// The remote file must be present, and the user must be online, or a labeled fallback is displayed.
const iconGlyphs={trait:'T',aspiration:'A',skill:'S',career:'C',world:'W',hobby:'H',pack:'P',venue:'V',lottrait:'LT',lotchallenge:'LC',tinyhome:'TH',lockedtrait:'LK'};
const LOCAL_ICON_URLS=new Map();
let localIconDB=null;
function openIconDB(){return new Promise((ok,bad)=>{if(!('indexedDB' in window)){bad(Error('indexedDB unavailable'));return;}const request=indexedDB.open('simstory-studio-v3-icons',1);request.onupgradeneeded=()=>request.result.createObjectStore('images');request.onerror=()=>bad(request.error);request.onsuccess=()=>{localIconDB=request.result;ok(localIconDB)}});}
async function restoreLocalIcons(){try{const db=await openIconDB();const tx=db.transaction('images','readonly'),store=tx.objectStore('images');const keys=await new Promise((ok,bad)=>{const req=store.getAllKeys();req.onsuccess=()=>ok(req.result);req.onerror=()=>bad(req.error)});for(const key of keys){const blob=await new Promise((ok,bad)=>{const req=store.get(key);req.onsuccess=()=>ok(req.result);req.onerror=()=>bad(req.error)});if(blob instanceof Blob){LOCAL_ICON_URLS.set(key,URL.createObjectURL(blob));}}if(LOCAL_ICON_URLS.size)render();}catch{/* Remote icons remain available if local image storage is unavailable. */}}
function iconFileKey(fileName){const normal=s=>String(s).toLowerCase().replace(/\.[^.]+$/,'').replace(/[^a-z0-9]/g,'');const n=normal(fileName);const exact=Object.entries(ICON_DATA).filter(([key,v])=>normal(v.file)===n);if(exact.length===1)return exact[0][0];const names=Object.entries(ICON_DATA).filter(([key])=>normal(key.split('|')[1])===n);return names.length===1?names[0][0]:null;}
async function importIcons(files){if(!files?.length)return;try{const db=localIconDB||await openIconDB();let count=0;for(const file of [...files]){if(!file.type.startsWith('image/')&&!/\.(png|jpe?g|webp)$/i.test(file.name))continue;const key=iconFileKey(file.name);if(!key)continue;const tx=db.transaction('images','readwrite');await new Promise((ok,bad)=>{const req=tx.objectStore('images').put(file,key);req.onsuccess=ok;req.onerror=()=>bad(req.error)});if(LOCAL_ICON_URLS.has(key))URL.revokeObjectURL(LOCAL_ICON_URLS.get(key));LOCAL_ICON_URLS.set(key,URL.createObjectURL(file));count++;}render();toast(count?`Loaded ${count} real game icon image${count===1?'':'s'} locally.`:'No matching filenames. See the icon catalog for examples.');}catch{toast('Local icon import unavailable in this browser. Online icons still work.')}}
// Hobby labels are separate from skills, but many hobbies use an actual in-game skill.
// Reuse the exact bundled skill icon instead of trying to find a nonexistent `hobby|...` key.
// A small curated list handles phrasing differences (e.g., Making nectar -> Nectar Making).
const HOBBY_SKILL_ICON_ALIASES = {
 "Writing a novel": "Writing",
 "Playing piano": "Piano",
 "Woodworking": "Handiness",
 "Yoga and meditation": "Wellness",
 "Running a retail store": "Entrepreneur",
 "DJ mixing": "DJ Mixing",
 "Learning to dance": "Dancing",
 "Pet training": "Pet Training",
 "Flower arranging": "Flower Arranging",
 "Rock climbing": "Rock Climbing",
 "Making nectar": "Nectar Making",
 "Horse riding": "Horse Riding",
 "Dating through Cupid’s Corner": "Romance",
 "Studying Thanatology": "Thanatology",
 "Writing wedding vows": "Writing",
 "Ghost hunting": "Medium",
 "Selling food from a stand": "Cooking",
 "Making waffles and pizza": "Cooking",
 "Crafting crystal jewelry": "Gemology",
 "Running a restaurant": "Gourmet Cooking",
 "Making pet portraits": "Photography"
};
function findGameIcon(type,name){
 const key=`${type}|${name}`;
 if(BUNDLED_ICON_PATHS[key]||LOCAL_ICON_URLS.has(key)) return {key,category:type};
 if(type==='hobby'){
   const linked=HOBBY_SKILL_ICON_ALIASES[name]||name;
   const skillKey=`skill|${linked}`;
   if(BUNDLED_ICON_PATHS[skillKey]||LOCAL_ICON_URLS.has(skillKey)) return {key:skillKey,category:'skill'};
 }
 return {key,category:type};
}
function gameIcon(type,name,inline=false){
 const lookup=findGameIcon(type,name);
 const imagePath=BUNDLED_ICON_PATHS[lookup.key];
 const local=LOCAL_ICON_URLS.get(lookup.key);
 const available=!!(imagePath||local);
 const classes=`gameicon ${inline?'mini':''} kind-${E(type)} ${available?'has-mapping':'no-mapping'}`;
 const kindLabel=type==='hobby'&&lookup.category==='skill'?'matching skill':''+type;
 const title=available?`${name} — bundled Sims 4 ${kindLabel} icon (offline)`:`No bundled ${type} icon available for ${name}`;
 const src=state.gameIcons?(local||imagePath):null;
 return `<span class="${classes}" role="img" aria-label="${E(title)}" title="${E(title)}"><span class="icon-fallback" aria-hidden="true">${E(iconGlyphs[type]||'–')}</span>${src?`<img data-sims-icon="1" data-attempt="bundled" alt="" loading="lazy" src="${E(src)}" />`:''}</span>`;
}

function packChip(id){const name=packName(id);return `<span class="pill">${gameIcon('pack',name,true)}${E(name)}</span>`;}
function packIconBlock(id){const name=packName(id);return `<div class="pack-thumb">${gameIcon('pack',name)}</div>`;}
function displayStat(label,value,packId,lockKey,desc){return `<div class="stat"><small>${E(label)}</small><div class="stat-row"><div class="val">${gameIcon(label.startsWith('Aspiration')?'aspiration':label.startsWith('Career')?'career':label.startsWith('Home')?'world':'hobby',value,true)}${E(value)}</div>${lockKey?lockBtn(lockKey):''}</div>${packId&&packId!=='base'?`<div class="sub">◈ ${E(packName(packId))}</div>`:''}${desc?`<div class="sub">${E(desc)}</div>`:''}</div>`}
const traitPlay={
 'Loner':'Protect their alone time, then allow one meaningful friendship to grow.',
 'Ambitious':'Choose promotions or big goals even when it creates a scheduling conflict.',
 'Creative':'Make something whenever they feel inspired—or frustrated.',
 'Perfectionist':'Redo something that fell short instead of taking the easy win.',
 'Romantic':'Let chemistry influence their choices, even when the timing is inconvenient.',
 'Gloomy':'Give quiet emotions room to shape the day and their art.',
 'Self-Assured':'Take the first step or speak their mind in a tense moment.',
 'Materialistic':'Choose an expensive wish and decide what they would sacrifice for it.',
 'Good':'Help someone even when it gets in the way of a personal goal.',
 'Neat':'Have one household boundary they will actually argue about.',
 'Jealous':'Notice what makes them insecure, then decide whether to talk or act.',
 'Outgoing':'Plan meetups and let the social calendar cause a little chaos.',
 'Family-Oriented':'Put an important family moment ahead of a personal plan.',
 'Horse Lover':'Make their relationship with a horse central to their routine.',
 'Macabre':'Explore an eerie location or have an unexpectedly deep conversation.',
 'Foodie':'Treat cooking or dining as a meaningful social ritual.'
};
function paletteHexes(r){return (r.colors||[]).map(c=>DATA.colors.find(x=>x.name===c)?.hex).filter(Boolean)}
function portrait(r){const colors=paletteHexes(r);const [a,b]=[colors[0]||'#8265b9',colors[1]||'#9cbdea'];return `<div class="sim-portrait" style="--avatar-a:${a};--avatar-b:${b}"><svg viewBox="0 0 146 158" role="img" aria-label="Stylized Sim silhouette in selected colors" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="bodyGrad" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs><path fill="#e9f2ff77" d="M0 145 73 0l73 145Z"/><path fill="#d8cbf8" stroke="#ffffff80" stroke-width="2" d="m72 1 22 40-22 29-22-29z"/><path fill="#67c9a4" d="M72 6 88 40 72 61 56 40Z"/><ellipse fill="#2f23499e" cx="73" cy="94" rx="33" ry="37"/><path fill="url(#bodyGrad)" d="M10 159c1-33 16-47 47-52l16 11 16-11c31 5 46 19 47 52Z"/><ellipse fill="#e8bf9e" cx="73" cy="92" rx="22" ry="30"/><path fill="#352846" d="M49 94c-9-47 11-53 23-53 16 0 32 11 25 52-4-8-9-15-14-20-12 9-23 12-34 11z"/><circle fill="#3c3046" cx="65" cy="93" r="2"/><circle fill="#3c3046" cx="81" cy="93" r="2"/><path stroke="#a86a69" stroke-width="2" fill="none" stroke-linecap="round" d="M67 105q6 5 12 0"/></svg><div class="portrait-caption">${E((r.colors||[]).slice(0,2).join(' + ')||'Signature palette')}</div></div>`}
function smallNotes(r){return `<div class="two-col"><div class="mini-note"><div class="notehead">${gameIcon('skill','Fitness',true)}<b>Strength</b></div>${E(r.strength)}</div><div class="mini-note"><div class="notehead">${gameIcon('skill','Logic',true)}<b>Growth edge</b></div>${E(r.weakness)}</div><div class="mini-note"><div class="notehead">${gameIcon('skill','Writing',true)}<b>Backstory detail</b></div>${E(r.background)}</div><div class="mini-note"><div class="notehead">${gameIcon('skill','Comedy',true)}<b>Quirk</b></div>${E(r.quirk)}</div></div>`}
function renderProfile(r){const ap=DATA.aspirations.find(x=>x.name===r.aspiration),cr=DATA.careers.find(x=>x.name===r.career),hb=DATA.hobbies.find(x=>x.name===r.hobby),wo=DATA.worlds.find(x=>x.name===r.world),style=DATA.styles.find(x=>x.name===r.style);return `<div class="result-top profile-top"><div class="profile-title"><div class="smalllabel" style="color:#d3bae7">✦ Your generated Sim</div><h2>${E(r.name)} ${lockBtn('name')}</h2><p>${E(r.age)} · ${E(r.lifeState||'Human')} · ${E(r.style)} · ${E(prettyTheme(r.story.theme))}</p></div>${portrait(r)}</div><div class="result-body"><div class="quick-game-icons"><div class="quick-game-title">✦ Your Sim in CAS <small>Actual game icons where available</small></div><div class="quick-game-grid"><div class="quick-game-item"><div class="quick-game-items">${r.traits.map(t=>gameIcon('trait',t)).join('')}</div><small>Traits</small></div><div class="quick-game-item">${gameIcon('aspiration',r.aspiration)}<small>Aspiration</small></div><div class="quick-game-item">${gameIcon('career',r.career)}<small>Career</small></div><div class="quick-game-item">${gameIcon('skill',r.skills?.[0]?.name||'')}<small>Primary skill</small></div></div></div><div class="result-section"><div class="rowline"><h3>♡ Personality & aesthetic</h3><span class="micro">Click ♧ to lock a result</span></div><div class="trait-stack">${r.traits.map((t,i)=>`<span class="trait">${gameIcon('trait',t)}<span>${E(t)}</span> ${lockBtn('trait'+i)}</span>`).join('')}</div><div class="roleplay-hints"><span class="smalllabel">Personality cues to play up</span>${(r.traits||[]).slice(0,3).map((t,i)=>`<p><b>${i+1}. ${E(t)}</b> — ${E(traitPlay[t]||'Let this trait guide their first reaction when something unexpected happens.')}</p>`).join('')}</div><div class="palette" style="margin-top:14px">${r.colors.map(c=>`<div class="palbox" title="${E(c)}" style="background:${DATA.colors.find(x=>x.name===c)?.hex||'#baa3e2'}"></div>`).join('')}${lockBtn('colors')}</div><div class="micro" style="margin-top:5px">${E(r.colors.join(' · '))}</div><div class="mini-note" style="margin-top:11px"><b>👗 Signature style: ${E(r.style)} ${lockBtn('style')}</b>Wardrobe: ${E(r.wardrobe)}.<br>Bedroom: ${E(r.room)}.</div></div><div class="result-section"><h3>◈ Their life</h3><div class="stat-grid">${displayStat('Aspiration',r.aspiration,ap?.pack,'aspiration')}${displayStat('Career / path',r.career,cr?.pack,'career')}${displayStat('Hobby / side quest',r.hobby,hb?.pack,'hobby')}${displayStat('Home world',r.world,wo?.pack,'world',r.worldDesc)}</div><div class="skill-focus"><div class="rowline"><h3>📈 Skills to grow or master</h3><span class="micro">Chosen skills stay fixed</span></div>${(r.skills||[]).map((s,i)=>`<div class="skill-row">${gameIcon('skill',s.name)}<div class="skill-descrip"><b>${E(s.name)}</b><small>${E(s.target||'Explore this skill')} · ${E(s.reason||'A creative direction for this Sim.')}</small></div>${lockBtn('skill'+i)}</div>`).join('')}<p class="micro">Aim for one major skill and one or two side interests—not everything at once.</p></div><div class="mini-note" style="margin-top:10px"><b>🏠 Life setup</b>${E(r.housing||'Surprise me')} · ${E(r.relationship||'Single')} · ${E(r.pronouns||'Pronouns open')}<br><b style="margin-top:8px">💸 Starting situation</b>${E({tight:'Very little money: keep the starter house truly modest.',modest:'A practical budget with room for a few personal touches.',comfortable:'Stable finances, but not unlimited spending.',wealthy:'Money is available; the more interesting challenge is what it cannot solve.'}[r.startingFunds]||r.startingFunds)}</div></div><div class="result-section"><h3>🎬 The storyline ${lockBtn('story')}</h3><div class="bigstory"><div class="storytitle">${E(r.story.title)}</div>${E(r.story.premise)}</div><div class="two-col" style="margin-top:11px"><div class="mini-note"><b>💜 Deepest desire</b>${E(r.story.want)}</div><div class="mini-note"><b>🌫️ Hidden fear</b>${E(r.story.fear)}</div><div class="mini-note"><b>⚡ Main tension</b>${E(r.story.friction)}</div><div class="mini-note"><b>🤫 Private secret</b>${E(r.story.secret)}</div></div></div><div class="result-section"><h3>🗓️ A four-week opening arc</h3>${r.story.weeks.map((w,i)=>`<div class="week"><div class="weeknum">W${i+1}</div><span>${E(w)}</span></div>`).join('')}</div><div class="result-section"><h3>🎯 Goals that give the save direction</h3><div class="two-col"><div><span class="smalllabel">Start here</span><ul class="small-list">${r.shortGoals.map(x=>`<li>${E(x)}</li>`).join('')}</ul></div><div><span class="smalllabel">Long-term possibilities</span><ul class="small-list">${r.longGoals.map(x=>`<li>${E(x)}</li>`).join('')}</ul></div></div></div><div class="result-section"><h3>🎭 Scenes & occasional drama</h3><ul class="small-list">${r.scenes.map(x=>`<li>${E(x)}</li>`).join('')}</ul><div class="mini-note"><b>🎲 Optional plot twist</b>${E(r.story.twist)}</div></div><div class="result-section"><h3>✧ Details that make them feel real</h3>${smallNotes(r)}<div class="mini-note" style="margin-top:10px"><b>👍 Suggested likes / dislikes</b>Likes: ${E(r.hobby)}, ${E(r.colors.slice(0,2).join(' and '))}, and meaningful progress.<br>Dislikes: ${E(r.traits.includes('Loner')?'crowded gatherings':'feeling dismissed')}, broken promises, and situations that trigger their biggest fear.</div>${r.notes?`<div class="mini-note" style="margin-top:10px"><b>📝 Your notes</b>${E(r.notes)}</div>`:''}<div style="margin-top:11px"><span class="smalllabel">Pack ingredients used</span><div>${r.packUsed.length?r.packUsed.map(id=>packChip(id)).join(''):'<span class="pill">'+gameIcon('pack','Base Game',true)+'Base Game only</span>'}</div></div></div><div class="actionrow"><button class="btn primary" data-action="save">♡ Save this Sim</button><button class="btn" data-action="copy">⧉ Copy</button><button class="btn" data-action="print">▤ Print</button><button class="btn" data-action="generate">↺ Reroll unlocked</button></div><div class="micro" style="margin-top:10px">Rerolls keep your chosen inputs and any results you locked with ♧. Change a fixed input on the left to change it.</div></div>`}
function renderHousehold(r){return `<div class="result-top"><div class="smalllabel" style="color:#d3bae7">✦ Your roommate save</div><h2>${E(r.title)}</h2><p>${r.count} Sims · ${E(r.world)} · four separate lives, one shared home</p></div><div class="result-body"><div class="result-section"><div class="bigstory"><div class="storytitle">🏡 The premise</div>${E(r.premise)}<div class="mini-note" style="margin-top:12px"><b>The shared dream</b>${E(r.goal)}</div></div></div><div class="result-section"><h3>♧ Meet the cast</h3><div class="household-list">${r.cast.map((s,i)=>`<div class="castcard"><span class="smalllabel">Roommate ${i+1}</span><strong>${E(s.name)}</strong><div class="statline"><span class="pill pink">${E(s.age)}</span><span class="pill">${E(s.style)}</span></div><div class="cast-icons">${s.traits.map(t=>gameIcon('trait',t,true)).join('')}${gameIcon('aspiration',s.aspiration,true)}${gameIcon('career',s.career,true)}</div><p><b>Traits:</b> ${E(s.traits.join(' · '))}<br><b>Aspiration:</b> ${E(s.aspiration)}<br><b>Career:</b> ${E(s.career)}<br><b>Hobby:</b> ${E(s.hobby)}<br><b>Focus skills:</b> ${E((s.skills||[]).map(k=>k.name).join(' · '))}</p><p>${E(s.story.premise)}</p><small>Secret: ${E(s.story.secret)}</small><div class="palette" style="margin-top:8px">${s.colors.map(c=>`<div class="palbox" style="height:9px;background:${DATA.colors.find(x=>x.name===c)?.hex||'#a99bc2'}" title="${E(c)}"></div>`).join('')}</div></div>`).join('')}</div></div><div class="result-section"><h3>💬 Relationship chemistry</h3>${r.relationships.map(x=>`<div class="ruleline"><b>${E(x.pair)}</b><br>${E(x.dynamic)}</div>`).join('')}<div class="mini-note"><b>⚡ Household conflict</b>${E(r.conflict)}</div></div><div class="result-section"><h3>🗓️ Your first month</h3>${r.weeks.map((w,i)=>`<div class="week"><span class="weeknum">W${i+1}</span><span>${E(w)}</span></div>`).join('')}<div class="notice">Try focusing on one roommate per session. You don't have to achieve every objective or keep every storyline going.</div></div><div class="result-section"><h3>◈ Pack ingredients used</h3>${r.packUsed.length?r.packUsed.map(id=>packChip(id)).join(''):'<span class="pill">'+gameIcon('pack','Base Game',true)+'Base Game</span>'}${r.notes?`<div class="mini-note" style="margin-top:10px"><b>Your notes</b>${E(r.notes)}</div>`:''}</div><div class="actionrow"><button class="btn primary" data-action="save">♡ Save household</button><button class="btn" data-action="copy">⧉ Copy</button><button class="btn" data-action="print">▤ Print</button><button class="btn" data-action="generate">↺ Another cast</button></div></div>`}
function iconsView(){
 const categories=[['all','All icons'],['trait','Traits'],['aspiration','Aspirations'],['skill','Skills'],['career','Careers'],['pack','Packs'],['venue','Venues'],['lottrait','Lot traits'],['lotchallenge','Lot challenges'],['tinyhome','Tiny homes'],['lockedtrait','Apartment traits']];
 const q=(state.iconSearch||'').toLowerCase().trim();
 const list=BUNDLED_ICON_CATALOG.filter(x=>(state.iconGroup==='all'||x.type===state.iconGroup)&&(`${x.name} ${x.type}`.toLowerCase().includes(q)));
 return `<div class="page-heading"><div><div class="eyebrow">◉ Bundled Sims 4 icon graphics</div><h1>The icon library.</h1><p>Browse actual PNG files for Sims traits, aspirations, skills, careers, packs, and build-mode gameplay icons—all included with this app and available offline.</p></div></div>
 <div class="card cardpad"><div class="icon-about"><strong>Your icons are already included</strong><p>The gallery now combines your <b>Build-A-Sim Icon Pack</b> and <b>Builder’s Icon Pack</b> uploads by deathbypufferfish. Generated Sims and the pack library reuse those matching files wherever possible; missing matches stay clearly labeled instead of using the wrong artwork.</p><div class="flexrow"><button class="btn tiny" data-action="toggle-icons">${state.gameIcons?'◉ Hide icons':'◉ Show icons'}</button><button class="btn tiny" data-action="import-icon-files">↑ Override with your own PNGs (optional)</button></div></div>
 <div class="icon-tools"><div class="icon-tabs">${categories.map(([id,title])=>`<button class="btn tiny ${state.iconGroup===id?'primary':''}" data-action="icon-group" data-id="${id}">${title}</button>`).join('')}</div><input class="searchinput" data-search="icons" value="${E(state.iconSearch||'')}" placeholder="Find Loner, Nifty Knitting, Library, Gremlins…" aria-label="Search game icons" /></div>
 <div class="micro">${list.length} bundled image files · no external image loading needed</div><div class="icon-gallery">${list.map(x=>`<div class="icon-entry">${`<span class="gameicon kind-${E(x.type)} has-mapping" title="${E(x.name)}" role="img" aria-label="${E(x.name)}"><span class="icon-fallback">${E(iconGlyphs[x.type]||'–')}</span>${state.gameIcons?`<img data-sims-icon="1" data-attempt="bundled" alt="" loading="lazy" src="${E(x.path)}"/>`:''}</span>`}<div class="icon-entry-text"><strong>${E(x.name)}</strong><small>${E(x.type).replace('lottrait','lot trait').replace('lotchallenge','lot challenge').replace('tinyhome','tiny home').replace('lockedtrait','apartment trait')} · bundled PNG</small></div></div>`).join('')}</div>${!list.length?'<div class="empty-state">No icons match this search.</div>':''}<p class="micro" style="margin-top:20px">Game artwork © EA / Maxis. Icon collections courtesy of deathbypufferfish. Independent, unofficial fan project.</p></div>`;
}
function packsView(){
 const q=(state.packSearch||'').toLowerCase().trim();
 const groups=['Expansion','Game Pack','Stuff Pack','Kit'];
 const filtered=DATA.packs.filter(p=>{
   const text=`${p.name} ${p.type} ${p.year}`.toLowerCase();
   return p.id==='base' || !q || text.includes(q);
 });
 const base=filtered.find(p=>p.id==='base');
 const sections=groups.map(group=>({group,items:filtered.filter(p=>p.id!=='base'&&p.type===group)})).filter(s=>s.items.length);
 const ownCount=state.owned.length;
 const activeCount=state.active.length;
 const packCard=(p,baseGame=false)=>`<article class="packitem ${baseGame?'enabled always':state.active.includes(p.id)?'enabled':''}"><div class="packhead">${packIconBlock(p.id)}<div><div class="ptitle">${E(p.name)}</div><small>${E(baseGame?'Included in every save':`${p.type} · ${p.year}`)}</small></div></div><div class="packflags">${baseGame?`<span class="pill mint">Always available</span>`:`<label class="flag"><input type="checkbox" data-pack="owned" value="${E(p.id)}" ${state.owned.includes(p.id)?'checked':''}/> Own</label><label class="flag ${state.owned.includes(p.id)?'':'disabled'}"><input type="checkbox" data-pack="active" value="${E(p.id)}" ${state.active.includes(p.id)?'checked':''} ${state.owned.includes(p.id)?'':'disabled'}/> Use in generator</label>`}</div></article>`;
 return `<div class="page-heading"><div><div class="eyebrow">◈ Your gameplay ingredients</div><h1>Pack Collection</h1><p>Track which packs you own and which ones the generator can pull from. Matching Builder’s Pack icons are shown wherever available.</p></div></div><div class="card cardpad"><div class="pack-toolbar"><div class="flexrow"><button class="btn tiny primary" data-action="packquick" data-id="owned">Use all owned</button><button class="btn tiny" data-action="packquick" data-id="featured">Load featured starter set</button><button class="btn tiny" data-action="packquick" data-id="none">Use none</button><button class="btn tiny" data-action="packquick" data-id="ownall">Mark all owned</button><button class="btn tiny" data-action="packquick" data-id="clearown">Clear owned</button></div><input class="searchinput" data-search="packs" value="${E(state.packSearch||'')}" placeholder="Search packs…" style="max-width:280px" aria-label="Search packs" /></div><div class="micro" style="margin-bottom:14px">${ownCount} owned pack${ownCount===1?'':'s'} · ${activeCount} currently active in the generator</div><div class="packsection"><h3>Base game</h3><div class="pack-grid">${base?packCard(base,true):''}</div></div>${sections.map(section=>`<div class="packsection"><h3>${E(section.group)}</h3><div class="pack-grid">${section.items.map(p=>packCard(p,false)).join('')}</div></div>`).join('')}${!base&&!sections.length?'<div class="empty-state">No packs match this search.</div>':''}<div class="notice" style="margin-top:16px">Tip: <b>Own</b> means you have the pack. <b>Use in generator</b> controls whether story ideas can pull content from it.</div></div>`;
}
function libraryView(){const q=state.librarySearch.toLowerCase();const all=state.library.filter(x=>[x.name,x.title,x.world,x.notes,x.libraryNote,...(x.traits||[])].filter(Boolean).join(' ').toLowerCase().includes(q));return `<div class="page-heading"><div><div class="eyebrow">♡ Your collection</div><h1>The idea vault.</h1><p>Save Sims, household setups, and plot directions you want to revisit. Everything stays on this device until you export it.</p></div></div><div class="card cardpad"><div class="pack-toolbar"><div class="flexrow"><button class="btn primary" data-action="export">↓ Export backup</button><button class="btn" data-action="import">↑ Import backup</button></div><input class="searchinput" data-search="library" value="${E(state.librarySearch)}" placeholder="Search saved Sims…" style="max-width:280px" aria-label="Search saved ideas" /></div><div class="micro" style="margin-bottom:14px">${state.library.length} saved ${state.library.length===1?'idea':'ideas'} · Import merges without overwriting existing ideas.</div>${all.length?`<div class="library-grid">${all.map(r=>`<article class="librarycard"><div class="rowline"><span class="pill ${r.kind==='household'?'blue':'pink'}">${r.kind==='household'?'Roommate household':'One Sim'}</span><small class="micro">${new Date(r.generatedAt||Date.now()).toLocaleDateString()}</small></div><h3>${E(r.kind==='household'?r.title:r.name)}</h3><p>${r.kind==='household'?`${r.count} Sims · ${E(r.world)}<br>${E(r.premise.slice(0,140))}…`:`${E(r.age)} · ${E(r.traits.join(' / '))}<br>${E(r.aspiration)} · ${E(r.world)}<br>${E(r.story.title)}`}</p><div class="bar">${(r.kind==='household'?r.cast[0].colors:r.colors).map(c=>`<span style="background:${DATA.colors.find(x=>x.name===c)?.hex||'#d9bee8'}"></span>`).join('')}</div><label class="smalllabel" for="note-${E(r.id)}">Private note</label><input class="noteinput" id="note-${E(r.id)}" data-note="${E(r.id)}" value="${E(r.libraryNote||'')}" placeholder="e.g. Save for the next legacy…"/><div class="actions"><button class="btn tiny primary" data-action="open-saved" data-id="${E(r.id)}">Open idea</button><button class="btn tiny" data-action="copy-saved" data-id="${E(r.id)}">Copy</button><button class="btn tiny danger" data-action="delete-saved" data-id="${E(r.id)}">Delete</button></div></article>`).join('')}</div>`:`<div class="empty-state"><div style="font-size:40px">♡</div><b>${q?'No matching saved ideas':'No saved ideas yet'}</b><span>${q?'Try a different search.':'Create a Sim or household, then hit Save.'}</span></div>`}<div class="prompt-vault"><h2>${gameIcon('skill','Research & Debate',true)} Saved inspiration prompts <span class="micro">(${state.savedPrompts.length})</span></h2>${state.savedPrompts.length?`<div class="saved-prompt-grid">${state.savedPrompts.map(s=>`<article class="saved-prompt"><span>${s.icon}</span><b>${E(s.cat)}</b><p>${E(s.text)}</p><button class="btn tiny danger" data-action="remove-prompt" data-id="${E(s.id)}">Remove</button></article>`).join('')}</div>`:'<p class="micro">Find something worth playing in the Inspo Deck? Save it here so you can pick up the idea later.</p>'}</div></div>`}
function sparkIdeas(){const packs=activePacks();const stories=DATA.stories.filter(x=>packs.has(x.pack));const story=pick(stories);const world=pick(allowed(DATA.worlds,packs).filter(x=>x.residential));const hobby=pick(allowed(DATA.hobbies,packs));const career=pick(allowed(DATA.careers,packs));const s1=pick(DATA.sceneStarts),s2=pick(DATA.sceneStarts.filter(x=>x!==s1));return [{cat:'Tonight’s scene',icon:'🎬',text:`${s1} Play the fallout without resetting anyone’s relationships.`},{cat:'One small goal',icon:'🎯',text:`Have a Sim in ${world?.name||'Willow Creek'} spend an afternoon trying ${hobby?.name?.toLowerCase()||'a new hobby'}. Let their mood decide how it goes.`},{cat:'Career subplot',icon:'💼',text:`A Sim considering ${career?.name||'a new career'} gets an unexpected opportunity, but must sacrifice one social plan to pursue it.`},{cat:'Plot twist',icon:'⚡',text:`${story?.twist||s2} Pick whichever reaction feels most in-character.`},{cat:'A new connection',icon:'💞',text:`${s2} Introduce an acquaintance who initially seems like an unlikely friend.`},{cat:'Longer storyline',icon:'📖',text:story?.premise?.replaceAll('{name}',pick(DATA.nameFirst)).replaceAll('{world}',world?.name||'Willow Creek').replaceAll('{career}',career?.name||'their career').replaceAll('{hobby}',hobby?.name||'a hobby')||'Start over in a new world and see who shows up.'}];}
const dilemmas=[
 {id:'proposal',label:'💍 A surprise proposal',q:'Should my Sim say yes to the proposal?',options:['Yes — say yes!','No — not right now','Not yet — ask for time']},
 {id:'inherit',label:'💰 Suspicious family inheritance',q:'Should my Sim accept the mysterious ancestor’s money?',options:['Take the money','Decline the offer','Take it, but add a complication']},
 {id:'baby',label:'🍼 Try for a baby',q:'Should these Sims try for a baby?',options:['Yes — start the next chapter','Not yet — wait','Maybe — let the relationship develop']},
 {id:'move',label:'🏠 Unexpected move',q:'Should my household move to a new world?',options:['Move!','Stay put','Make a compromise first']},
 {id:'career',label:'💼 Quit a job',q:'Should my Sim quit their career to follow a dream?',options:['Quit and take the leap','Keep the steady job','Pursue it as a side hustle']},
 {id:'romance',label:'💕 Second chance',q:'Should my Sim give their ex another chance?',options:['Yes — try again','No — move on','One date, then decide']},
 {id:'custom',label:'✍️ My own dilemma',q:'',options:[]}
];
function spotlightView(){
 const s=state.sparks||sparkIdeas();const idx=state.spotlight;
 if(idx<0||!s[idx])return '';
 const x=s[idx];const detail=[
  ['Set the scene','Pick the Sim this fits best and give them a believable reason to get involved.'],
  ['Add a wrinkle','Let a relationship, a money problem, or a surprise visitor complicate things.'],
  ['Play the outcome','Play one in-game day. Keep whatever actually happens—even if it changes the plan.']
 ];
 return `<div class="spotlight" id="spotlight"><div class="rowline"><span class="smalllabel">✦ Tonight’s selected idea</span><button class="iconbtn" data-action="close-spark" aria-label="Close selected idea">✕</button></div><h2>${E(x.icon)} ${E(x.cat)}</h2><p>${E(x.text)}</p><div class="beat-grid">${detail.map(([h,p],i)=>`<div class="beat"><span>0${i+1}</span><b>${E(h)}</b><small>${E(p)}</small></div>`).join('')}</div><div class="flexrow"><button class="btn primary" data-action="pin-spark" data-id="${idx}">♡ Save to idea vault</button><button class="btn" data-action="reroll-spark" data-id="${idx}">↻ Different idea in this slot</button></div></div>`;
}
function diceView(){
 const d=state.dice;
 const opts= d.preset==='custom'?d.custom.split(/[,\n|]/).map(x=>x.trim()).filter(Boolean):dilemmas.find(x=>x.id===d.preset)?.options||[];
 return `<section class="dice-panel" id="decision-dice"><div class="dice-intro"><div><span class="smalllabel">🎲 Your in-game tie-breaker</span><h2>Decision Dice</h2><p>For proposals, surprise inheritance offers, trying for a baby, moving out—or literally any Sims dilemma. The result is a nudge, not a rule.</p></div><div class="dice-art" aria-hidden="true"><div class="die-face">${d.result?'✦':'⚄'}</div></div></div><div class="dice-fields"><div class="field"><label for="d-preset">Quick dilemma</label><select id="d-preset" data-dice="preset">${dilemmas.map(o=>`<option value="${o.id}" ${d.preset===o.id?'selected':''}>${E(o.label)}</option>`).join('')}</select></div><div class="field"><label for="d-mode">How should the dice decide?</label><select id="d-mode" data-dice="mode">${[['nuanced','Yes / No / Maybe'],['binary','Yes or No'],['options','Dilemma-specific choices'],['d6','Roll a six-sided die']].map(([v,t])=>`<option value="${v}" ${d.mode===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="d-bias">Chance style</label><select id="d-bias" data-dice="bias">${[['even','Balanced odds'],['bold','Favor the bold / yes'],['cautious','Favor the cautious / no']].map(([v,t])=>`<option value="${v}" ${d.bias===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field wide"><label for="d-question">Your question</label><input id="d-question" data-dice="question" value="${E(d.question)}" maxlength="240" placeholder="e.g. Should she break up with him?" /></div>${d.preset==='custom'?`<div class="field wide"><label for="d-custom">Custom outcomes (optional; separate with commas)</label><input id="d-custom" data-dice="custom" value="${E(d.custom)}" placeholder="Go for it, Wait a week, Walk away" /></div>`:''}</div><div class="dice-bottom"><button class="btn primary big" data-action="roll-dice">🎲 Roll the dice</button>${d.result?`<div class="dice-result" aria-live="polite"><span class="smalllabel">The dice say…</span><strong>${E(d.result.answer)}</strong><p>${E(d.result.note)}</p><small>${E(d.result.question)}</small></div>`:'<span class="micro">Pick a preset or type your own question.</span>'}</div>${d.history?.length?`<details class="dice-history"><summary>Previous rolls (${d.history.length})</summary>${d.history.slice(0,6).map(x=>`<div><b>${E(x.answer)}</b> — ${E(x.question)}</div>`).join('')}</details>`:''}</section>`;
}
function sparksView(){const s=state.sparks||sparkIdeas();return `<div class="page-heading"><div><div class="eyebrow">⚡ Everyday gameplay inspiration</div><h1>What should happen next?</h1><p>Pick a storyline to actually play, or let the Decision Dice break a tie.</p></div><button class="btn primary" data-action="sparks">↺ Shuffle all prompts</button></div><div class="deck-note">✨ <b>Inspo Deck:</b> Choose a card to turn into a playable three-beat scene. <b>Decision Dice:</b> Toss-up choices when the game throws you a curveball.</div><div class="spark-grid">${s.map((x,i)=>`<article class="sparkcard ${state.spotlight===i?'selected':''}"><div class="symbol">${x.icon}</div><h3>${E(x.cat)}</h3><p>${E(x.text)}</p><div class="spark-actions"><button class="btn tiny primary" data-action="play-spark" data-id="${i}">▶ Play this idea</button><button class="btn tiny" data-action="pin-spark" data-id="${i}" title="Save prompt to vault">♡ Save</button><button class="btn tiny icon-only" data-action="reroll-spark" data-id="${i}" title="Reroll this prompt" aria-label="Reroll ${E(x.cat)}">↻</button></div></article>`).join('')}</div>${spotlightView()}${diceView()}<div class="notice" style="margin-top:16px">If gameplay takes a better turn, follow it. These are prompts and chance rolls—not rules you have to obey.</div>`}
function diceRoll(){
 const d=state.dice;const specific=dilemmas.find(x=>x.id===d.preset);
 const namedOptions=d.preset==='custom'?d.custom.split(/[,\n|]/).map(x=>x.trim()).filter(Boolean):specific?.options||[];
 const options=d.mode==='d6'?['1','2','3','4','5','6']:d.mode==='binary'?['Yes','No']:d.mode==='nuanced'?['Yes','No','Maybe / Not yet']:(namedOptions.length>=2?namedOptions:['Yes','No','Maybe / Not yet']);
 let weights=options.map((_,i)=>1);
 if(d.bias!=='even'&&d.mode!=='d6'){
   if(d.bias==='bold')weights[0]=3;
   if(d.bias==='cautious')weights[1]=3;
 }
 let r=Math.random()*weights.reduce((a,b)=>a+b,0),i=0;
 for(;i<options.length-1;i++){r-=weights[i];if(r<0)break;}
 const answer=options[i];
 const notes=d.mode==='d6'?{1:'An unexpected setback. Improvise a detour.',2:'A complication appears. Keep it interesting.',3:'A cautious step forward.',4:'Something small goes your way.',5:'Take the opportunity with a twist.',6:'A big lucky break! Run with it.'}:
 {Yes:'Go for it. Let your Sim react to what comes next.',No:'Not this time. A closed door can make a better storyline.','Maybe / Not yet':'Put it off for one in-game day and see what changes.'};
 const result={question:(d.question||specific?.q||'What happens next?').trim(),answer,note:notes[answer]|| (i===0?'Lean into this choice and play out the consequences.':i===1?'Give the alternative some breathing room.':'Make it a subplot and see how the Sims respond.'),at:new Date().toISOString()};
 d.result=result;d.history=[result,...(d.history||[])].slice(0,12);persist();render();document.getElementById('decision-dice')?.scrollIntoView({block:'nearest',behavior:'smooth'});
}

function render(){const el=$('#app');el.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}<div class="appcontent">${state.tab==='studio'?studio():state.tab==='packs'?packsView():state.tab==='library'?libraryView():state.tab==='icons'?iconsView():sparksView()}</div></main></div>`;document.querySelectorAll('[data-panel]').forEach(x=>x.addEventListener('toggle',()=>{state.sections[x.dataset.panel]=x.open;persist()}));}
function validatePrefs(){const p=state.prefs,sets=activePacks();for(const k of ['trait0','trait1','trait2','aspiration','career','hobby','world','skill0','skill1','skill2']){const list=k.startsWith('trait')?DATA.traits: k==='aspiration'?DATA.aspirations:k==='career'?DATA.careers:k==='hobby'?DATA.hobbies:k.startsWith('skill')?DATA.skills:DATA.worlds;if(p[k]&&!allowed(list,sets).some(x=>x.name===p[k]))p[k]=''}if(p.story&&!DATA.stories.some(x=>x.title===p.story&&sets.has(x.pack)))p.story='';if(p.lifeState&&!['Human','Ghost'].includes(p.lifeState)&&!({Alien:'gtw',Vampire:'vamp',Mermaid:'il',Spellcaster:'magic',Werewolf:'were',Fairy:'nature'}[p.lifeState]&&sets.has(({Alien:'gtw',Vampire:'vamp',Mermaid:'il',Spellcaster:'magic',Werewolf:'were',Fairy:'nature'})[p.lifeState])))p.lifeState='Human';if(state.mode==='single'&&state.current?.kind==='single')state.locks=state.locks.filter(k=>{if(k.startsWith('trait'))return allowed(DATA.traits,sets).some(x=>x.name===state.current.traits[Number(k.slice(-1))]);const list=k==='career'?DATA.careers:k==='hobby'?DATA.hobbies:k==='aspiration'?DATA.aspirations:k==='world'?DATA.worlds:k.startsWith('skill')?DATA.skills:null;return !list||allowed(list,sets).some(x=>x.name===(k.startsWith('skill')?state.current.skills?.[Number(k.slice(-1))]?.name:state.current[k]))})}
function clearPrefs(){state.prefs={...samplePrefs(),trait0:'',colors:[]};state.locks=[];state.current=null;persist();render()}
function getText(r){if(!r)return'';if(r.kind==='household')return `${r.title}\nLocation: ${r.world}\n${r.premise}\nHousehold goal: ${r.goal}\nConflict: ${r.conflict}\n\n${r.cast.map((s,i)=>`ROOMMATE ${i+1}: ${s.name}\n${s.age} · ${s.traits.join(', ')}\nAspiration: ${s.aspiration}\nCareer: ${s.career}\nHobby: ${s.hobby}\nSkills: ${(s.skills||[]).map(x=>x.name).join(', ')}\nStyle/colors: ${s.style} · ${s.colors.join(', ')}\n${s.story.premise}\nSecret: ${s.story.secret}`).join('\n\n')}\n\nRELATIONSHIPS\n${r.relationships.map(x=>x.pair+': '+x.dynamic).join('\n')}\n\nFOUR WEEKS\n${r.weeks.map((s,i)=>`${i+1}. ${s}`).join('\n')}${r.notes?'\nNotes: '+r.notes:''}`;
 return `${r.name} · ${r.age}\nTraits: ${r.traits.join(', ')}\nAspiration: ${r.aspiration}\nCareer: ${r.career}\nRelationship: ${r.relationship||'Single'}\nHousing: ${r.housing||'Surprise me'}\nHobby: ${r.hobby}\nFocus skills: ${(r.skills||[]).map(x=>x.name+' ('+x.target+')').join(', ')}\nWorld: ${r.world}\nStyle: ${r.style}\nColors: ${r.colors.join(', ')}\nWardrobe: ${r.wardrobe}\nRoom: ${r.room}\n\n${r.story.title}\n${r.story.premise}\nDesire: ${r.story.want}\nFear: ${r.story.fear}\nConflict: ${r.story.friction}\nSecret: ${r.story.secret}\n\n4-WEEK ARC\n${r.story.weeks.map((x,i)=>`Week ${i+1}: ${x}`).join('\n')}\n\nSHORT-TERM GOALS\n${r.shortGoals.map(x=>'- '+x).join('\n')}\n\nLONG-TERM GOALS\n${r.longGoals.map(x=>'- '+x).join('\n')}\n\nPLOT TWIST\n${r.story.twist}\n\nBackground: ${r.background}\nQuirk: ${r.quirk}\nStrength: ${r.strength}\nGrowth edge: ${r.weakness}${r.notes?'\nNotes: '+r.notes:''}`}
async function copyText(str){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(str);else{const t=document.createElement('textarea');t.value=str;t.style.position='fixed';t.style.left='-9999px';document.body.appendChild(t);t.select();if(!document.execCommand('copy'))throw Error('clipboard');t.remove()}toast('Copied to clipboard ✧')}catch{toast('Clipboard blocked. Use Export to save your ideas instead.')}}
function fileDownload(name,data,mime){const blob=new Blob([data],{type:mime});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function handleAction(action,id){switch(action){
 case 'import-icon-files':$('#iconFiles').click();break;
 case 'import-icon-folder':$('#iconFolder').click();break;
 case 'icon-group':state.iconGroup=id;persist();render();break;
 case 'tab':state.tab=id;persist();render();window.scrollTo({top:0,behavior:'auto'});break;
 case 'mode':state.mode=id;state.current=null;state.locks=[];persist();render();break;
 case 'color':state.prefs.colors=state.prefs.colors.includes(id)?state.prefs.colors.filter(c=>c!==id):[...state.prefs.colors,id];persist();render();break;
 case 'generate':generate();break;
 case 'reset':clearPrefs();toast('Character choices reset. Your pack collection and saved ideas are safe.');break;
 case 'lock':state.locks=state.locks.includes(id)?state.locks.filter(x=>x!==id):[...state.locks,id];persist();render();break;
 case 'save':if(!state.current)return;{const r=JSON.parse(JSON.stringify(state.current));r.id='s'+Date.now()+'_'+Math.floor(Math.random()*1e6);state.library.unshift(r);persist();render();toast('Saved to your idea vault ♡');}break;
 case 'copy':copyText(getText(state.current));break;
 case 'print':window.print();break;
 case 'packquick':if(id==='owned')state.active=[...state.owned];if(id==='featured'){state.owned=uniq([...state.owned,...DATA.featured]);state.active=[...DATA.featured]}if(id==='none')state.active=[];if(id==='ownall')state.owned=DATA.packs.filter(x=>x.id!=='base').map(x=>x.id);if(id==='clearown'){state.owned=[];state.active=[]}validatePrefs();persist();render();break;
 case 'open-saved':{const r=state.library.find(x=>x.id===id);if(!r)return;state.current=JSON.parse(JSON.stringify(r));state.mode=r.kind==='household'?'household':'single';state.prefs={...samplePrefs(),trait0:'',colors:[],age:r.kind==='household'?r.cast[0].age:r.age,householdCount:r.count||4};state.locks=r.kind==='single'?['name','trait0','trait1','trait2','aspiration','career','hobby','world','skill0','skill1','skill2','style','colors','story']:[];state.tab='studio';persist();render();window.scrollTo({top:0,behavior:'auto'});toast('Loaded saved idea. You can reroll or customize it.');}break;
 case 'copy-saved':{const r=state.library.find(x=>x.id===id);if(r)copyText(getText(r));}break;
 case 'delete-saved':if(confirm('Delete this saved idea? This cannot be undone unless you have exported a backup.')){state.library=state.library.filter(x=>x.id!==id);persist();render();toast('Saved idea deleted.')}break;
 case 'export':fileDownload(`simstory-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'SimStory Studio',version:2,exportedAt:new Date().toISOString(),owned:state.owned,active:state.active,library:state.library,savedPrompts:state.savedPrompts,dice:state.dice,prefs:state.prefs},null,2),'application/json');toast('Backup downloaded.');break;
 case 'import':$('#importFile').click();break;
 case 'sparks':state.sparks=sparkIdeas();state.spotlight=-1;persist();render();break;
 case 'play-spark':state.spotlight=Number(id);persist();render();document.getElementById('spotlight')?.scrollIntoView({block:'nearest',behavior:'smooth'});break;
 case 'close-spark':state.spotlight=-1;persist();render();break;
 case 'reroll-spark':{const idx=Number(id);state.sparks[idx]=sparkIdeas()[idx];persist();render();break;}
 case 'pin-spark':{const s=state.sparks?.[Number(id)];if(s){const exists=state.savedPrompts.some(p=>p.text===s.text);if(!exists)state.savedPrompts.unshift({...s,id:'p'+Date.now()+'_'+Math.floor(Math.random()*1e6),created:new Date().toISOString()});persist();render();toast(exists?'This prompt is already saved.':'Added to your Inspo Vault ♡');}break;}
 case 'remove-prompt':if(confirm('Remove this saved inspiration prompt?')){state.savedPrompts=state.savedPrompts.filter(x=>x.id!==id);persist();render();}break;
 case 'roll-dice':diceRoll();break;
 case 'toggle-icons':state.gameIcons=!state.gameIcons;persist();render();break;
 case 'copytext':copyText(id);break;
 }}
document.addEventListener('error',e=>{const im=e.target;if(!(im instanceof HTMLImageElement)||!im.dataset.simsIcon)return;im.closest('.gameicon')?.classList.add('image-missing');im.remove();},true);
document.addEventListener('load',e=>{const im=e.target;if(im instanceof HTMLImageElement&&im.dataset.simsIcon)im.closest('.gameicon')?.classList.add('image-loaded');},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.closest('summary'))return;handleAction(b.dataset.action,b.dataset.id||'')});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.pack){const id=el.value,kind=el.dataset.pack;if(kind==='owned'){if(el.checked)state.owned=uniq([...state.owned,id]);else{state.owned=state.owned.filter(x=>x!==id);state.active=state.active.filter(x=>x!==id)}}else if(kind==='active'){if(el.checked){state.active=uniq([...state.active,id]);state.owned=uniq([...state.owned,id])}else state.active=state.active.filter(x=>x!==id)}validatePrefs();persist();render();return}if(el.dataset.dice){state.dice[el.dataset.dice]=el.value;if(el.dataset.dice==='preset'){const preset=dilemmas.find(x=>x.id===el.value);state.dice.question=preset?.q||'';}state.dice.result=null;persist();if(el.tagName==='SELECT')render();return}if(el.dataset.pref){let value=el.value;state.prefs[el.dataset.pref]=el.dataset.pref==='householdCount'?Number(value):value;persist();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.dice&&['INPUT','TEXTAREA'].includes(el.tagName)){state.dice[el.dataset.dice]=el.value;persist();return}if(el.dataset.pref&&['INPUT','TEXTAREA'].includes(el.tagName)){state.prefs[el.dataset.pref]=el.value;persist();return}if(el.dataset.note){const r=state.library.find(x=>x.id===el.dataset.note);if(r){r.libraryNote=el.value;persist()}return}if(el.dataset.search){const key=el.dataset.search==='packs'?'packSearch':el.dataset.search==='icons'?'iconSearch':'librarySearch';state[key]=el.value;const id=el.dataset.search;const pos=el.selectionStart;render();const next=document.querySelector(`[data-search="${id}"]`);next?.focus();try{next?.setSelectionRange(pos,pos)}catch{};}});
$('#iconFiles').addEventListener('change',async e=>{await importIcons(e.target.files);e.target.value='';});
$('#iconFolder').addEventListener('change',async e=>{await importIcons(e.target.files);e.target.value='';});
$('#importFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(data.app!=='SimStory Studio'||!Array.isArray(data.library))throw Error('format');const ids=new Set(state.library.map(x=>x.id));for(const r of data.library){if(r&&r.id&&['single','household'].includes(r.kind)&&!ids.has(r.id)){state.library.push(r);ids.add(r.id)}}if(Array.isArray(data.savedPrompts)){const ids=new Set(state.savedPrompts.map(x=>x.id));for(const prompt of data.savedPrompts){if(prompt?.id&&typeof prompt.text==='string'&&!ids.has(prompt.id)){state.savedPrompts.push(prompt);ids.add(prompt.id)}}}if(Array.isArray(data.owned))state.owned=uniq([...state.owned,...data.owned.filter(id=>DATA.packs.some(p=>p.id===id))]);if(Array.isArray(data.active))state.active=uniq([...state.active,...data.active.filter(id=>state.owned.includes(id))]);persist();render();toast('Backup imported and merged into your library ♡')}catch{toast('This does not look like a SimStory Studio backup.')}finally{e.target.value=''}});
if(!state.current){state.current=buildProfile();state.history=[state.current];persist()}
if(!state.sparks)state.sparks=sparkIdeas();
render();
restoreLocalIcons();
})();
